<script setup lang="tsx">
import { computed, WatchStopHandle } from "vue";
import { onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, ShowErrorTips, ShowTextTipsInfo } from "@/util/tips";
import { GetProblemList, GetProblemTagList, ParseProblem, ProblemAttemptStatus, PostProblemCrawl } from "@/apis/problem.ts";
import { Problem, ProblemTag, ProblemView } from "@/types/problem.ts";
import { AuthType } from "@/auth";
import { useUserStore } from "@/stores/user.ts";
import { handleGotoProblem } from "@/util/router.ts";
import type { TableRowData, TNodeReturnValue } from "tdesign-vue-next";
import type { CellParams } from "@/types/table";
import { useBreakpoint } from "@/composables/useBreakpoint";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const userStore = useUserStore();
const { isMobile } = useBreakpoint();

let viewActive = false;
let watchHandle: WatchStopHandle | null = null;

const tagsMap = {} as { [key: number]: ProblemTag };
let problemAttemptStatus = {} as { [key: string]: ProblemAttemptStatus };

const isCrawling = ref(false);

const hasEditAuth = computed(() => {
  return userStore.hasAuth(AuthType.ManageProblem);
});

// 说明：tdesign 的 BaseTableCol<T> 是递归类型（children?: BaseTableCol<T>[]），本页 cell 返回 JSX，
// 直接标注会触发 TS2589（Type instantiation is excessively deep），故按其字段构造一个非递归的等价列类型
type ProblemListColumn = {
  title: string;
  colKey: string;
  width?: number | string;
  minWidth?: number | string;
  cell?: (_h: unknown, data: CellParams<TableRowData>) => TNodeReturnValue;
};

const fullColumns: ProblemListColumn[] = [
  {
    title: "标识",
    colKey: "key",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const theme = getProblemIdTheme(data.row.id);
      return (
        <t-button variant="dashed" theme={theme} onClick={() => handleGotoProblem(data.row.key)}>
          {data.row.key}
        </t-button>
      );
    },
  },
  {
    title: "标题",
    colKey: "title",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      return (
        <t-button variant="text" onClick={() => handleGotoProblem(data.row.key)}>
          {data.row.title}
        </t-button>
      );
    },
  },
  {
    title: "难度",
    colKey: "difficulty",
    width: 80,
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const grade = data.row.difficulty as number | undefined;
      if (!grade) {
        return "";
      }
      const themeMap: Record<number, string> = {
        1: "success",
        2: "primary",
        3: "warning",
        4: "danger",
        5: "danger",
      };
      return (
        <t-tag theme={(themeMap[grade] as "success" | "primary" | "warning" | "danger") || "default"} variant="light">
          {data.row.difficultyName || grade}
        </t-tag>
      );
    },
  },
  {
    title: "标签",
    colKey: "tags",
    cell: (_h: unknown, data: CellParams<TableRowData>) => {
      const tags = data.row.tags;
      if (!tags || tags.length === 0) {
        return "";
      }
      const tagButtons = [];
      for (let i = 0; i < tags.length; i++) {
        const tag = tags[i];
        tagButtons.push(
          <t-button key={i} theme="default" variant="outline" size="small" onClick={() => handleClickTag(tag)}>
            {tag.name}
          </t-button>
        );
      }
      return <t-space>{tagButtons}</t-space>;
    },
  },
  {
    title: "正确",
    colKey: "accept",
  },
  {
    title: "提交",
    colKey: "attempt",
  },
];

const listColumns = computed(() =>
  isMobile.value ? fullColumns.filter((c) => c.colKey !== "tags") : fullColumns
);

const dataLoading = ref(false);

let currentPage = 1;
let currentPageSize = 50;

const pagination = ref({
  current: currentPage,
  pageSize: currentPageSize,
  defaultCurrent: currentPage,
  defaultPageSize: currentPageSize,
  total: 0,
  pageSizeOptions: [50, 100],
});

const problemViews = ref<ProblemView[]>();
const problemTags = ref<ProblemTag[]>();

// 标签云最多渲染这么多个。取数仍是全量——题目上挂的标签要能靠 tagsMap 显示名字，
// 只取前 N 个会让第 N+1 个之后的标签在题目列表里显示成空。
const TAG_CLOUD_LIMIT = 100;
const visibleTags = computed(() => (problemTags.value ?? []).slice(0, TAG_CLOUD_LIMIT));
const hiddenTagCount = computed(() => Math.max(0, (problemTags.value?.length ?? 0) - TAG_CLOUD_LIMIT));

// 「… 还有 N 个」→ 标签单页。侧栏渲染不下全部，单页里能看到所有概念，
// 以及每个概念的同义词（那里才展示别名，侧栏只出现通用名）
const goTagPage = () => {
  router.push({ name: "problem-tags" });
};

const ojOptions = [
  { label: "DidaOJ", value: "didaoj" },
  { label: "HDU", value: "hdu" },
  { label: "POJ", value: "poj" },
  { label: "NYOJ", value: "nyoj" },
  { label: "ZZNU", value: "zznu" },
  { label: "HAUT", value: "haut" },
  { label: "Codeforces", value: "codeforces" },
];

const searchProblemForm = ref({
  oj: "",
  title: "",
  tag: "",
  // 多个标签之间的关系：any 命中任一（默认）/ all 每组都要具备。
  // 标签输入支持逗号、顿号分隔，如「并查集,贪心」+ all = 两个主题都用到
  tagMode: "any",
  difficulty: 0,
  private: false,
});

// 标签筛选的多选值（叫法名数组）。与 searchProblemForm.tag 是同一份状态的两个视图：
// 多选框面向用户，tag 字符串是发给后端与写进 URL 的形态（逗号拼接，后端按分隔符切分）。
// 之所以不把 tag 直接改成数组：URL 里 tag=并查集,贪心 是老格式，改了会让收藏的链接失效。
const selectedTags = ref<string[]>([]);

// 标签选项：标签列表只返回通用名行，所以选项就是「概念名」。
// 但检索支持任一叫法，因此过滤用自定义 filter 匹配全部叫法——
// 用户记得的是「DSU」而不是「并查集」，只能按 label 过滤会让他觉得搜不到。
type TagSelectOption = { label: string; value: string; members: string[] };

const tagOptions = computed<TagSelectOption[]>(() =>
  (problemTags.value ?? []).map((tag) => ({
    label: tag.name,
    value: tag.name,
    members: (tag.members ?? []).map((m) => m.name),
  }))
);

const filterTagOption = (filterValue: string, option: TagSelectOption) => {
  const kw = filterValue.trim().toLowerCase();
  if (!kw) {
    return true;
  }
  if (option.label.toLowerCase().includes(kw)) {
    return true;
  }
  return option.members.some((name) => name.toLowerCase().includes(kw));
};

// 已选标签 → 提交串。用逗号拼接（后端 tagSpecSeparators 认中英文逗号与顿号）
const syncTagString = () => {
  searchProblemForm.value.tag = selectedTags.value.join(",");
};

// URL 里的 tag 串 → 多选值。按与后端相同的分隔符切分，避免「URL 里明明有两个标签、
// 多选框却只显示一个」这种状态不一致
const parseTagString = (raw: string) =>
  raw
    .split(/[,，、]/)
    .map((s) => s.trim())
    .filter((s) => s !== "");

// AI 审阅综合难度档（入门/基础/进阶/困难/挑战）；0 表示不限
const difficultyOptions = [
  { label: "全部难度", value: 0 },
  { label: "入门", value: 1 },
  { label: "基础", value: 2 },
  { label: "进阶", value: 3 },
  { label: "困难", value: 4 },
  { label: "挑战", value: 5 },
];

const crawlProblemForm = ref({
  oj: "",
  problem: "",
});

const getProblemIdTheme = (id: string) => {
  if (!id) {
    return "default";
  }
  if (!problemAttemptStatus) {
    return "default";
  }
  const status = problemAttemptStatus[id];
  if (!status) {
    return "default";
  }
  switch (status) {
    case ProblemAttemptStatus.Accept:
      return "success";
    case ProblemAttemptStatus.Attempt:
      return "warning";
    default:
      return "default";
  }
};

const handleClickSearch = async () => {
  syncTagString();
  // 更新 URL 查询参数
  await router.push({
    query: {
      ...route.query,
      oj: searchProblemForm.value.oj,
      title: searchProblemForm.value.title,
      tag: searchProblemForm.value.tag,
      tag_mode: searchProblemForm.value.tagMode === "all" ? "all" : "",
      difficulty: searchProblemForm.value.difficulty > 0 ? String(searchProblemForm.value.difficulty) : "",
      private: searchProblemForm.value.private ? "1" : "0",
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

const handleClickReset = async () => {
  searchProblemForm.value.oj = "";
  searchProblemForm.value.title = "";
  searchProblemForm.value.tag = "";
  searchProblemForm.value.tagMode = "any";
  searchProblemForm.value.difficulty = 0;
  searchProblemForm.value.private = false;
  selectedTags.value = [];

  // 更新 URL 查询参数
  await router.push({
    query: {
      ...route.query,
      oj: "",
      title: "",
      tag: "",
      tag_mode: "",
      difficulty: "",
      private: "0",
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

// 移动端筛选 Drawer 显隐状态
const showFilterDrawer = ref(false);

// 当前已激活的筛选条件数量，用于「筛选」按钮徽标提示
const activeFilterCount = computed(() => {
  let count = 0;
  if (searchProblemForm.value.oj) count++;
  if (searchProblemForm.value.title) count++;
  if (searchProblemForm.value.tag) count++;
  if (searchProblemForm.value.difficulty > 0) count++;
  if (searchProblemForm.value.private) count++;
  return count;
});

// 移动端 Drawer 中的搜索：复用桌面端逻辑，搜索后关闭抽屉
const handleDrawerSearch = async () => {
  await handleClickSearch();
  showFilterDrawer.value = false;
};

// 移动端 Drawer 中的重置：复用桌面端逻辑
const handleDrawerReset = async () => {
  await handleClickReset();
};

const handleClickCrawl = async () => {
  try {
    isCrawling.value = true;
    const res = await PostProblemCrawl(crawlProblemForm.value.oj, crawlProblemForm.value.problem);
    if (res.code === 0) {
      ShowTextTipsInfo(globalProperties, "搜索成功");
      await router.push({
        name: "problem-detail",
        params: { problemKey: res.data },
      });
    } else {
      ShowErrorTips(globalProperties, res.code);
    }
  } catch (err) {
    console.error(err);
    ShowErrorTips(globalProperties, GetCommonErrorCode());
  } finally {
    isCrawling.value = false;
  }
};

// 点题目行上的标签 = 按它筛题。**追加**而不是替换：多选筛选框会把已选标签
// 全部显示成 chip，状态始终可见；追加不会静默丢掉用户已经设好的条件。
// 再点一次同一个标签则移除（等于反选），方便撤销。
const handleClickTag = (tag: ProblemTag) => {
  if (!tag) {
    return;
  }
  toggleTagFilter(tag.name);
};

// 追加/移除一个标签条件，然后立刻按新条件检索（走 URL，与手动搜索同一条链路）
const toggleTagFilter = async (name: string) => {
  const current = selectedTags.value;
  selectedTags.value = current.includes(name)
    ? current.filter((t) => t !== name)
    : [...current, name];
  syncTagString();
  await router.push({
    query: {
      ...route.query,
      title: "",
      tag: searchProblemForm.value.tag,
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

const handleClickCreate = () => {
  router.push({ name: "manage-problem-create" });
};

const fetchData = async (paginationInfo: { current: number; pageSize: number }, needLoading: boolean) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  try {
    const { current, pageSize } = paginationInfo;
    const res = await GetProblemList(
      searchProblemForm.value.oj,
      searchProblemForm.value.title,
      searchProblemForm.value.tag,
      searchProblemForm.value.private,
      current,
      pageSize,
      searchProblemForm.value.difficulty,
      searchProblemForm.value.tagMode
    );
    problemViews.value = [];
    if (res.code === 0) {
      const responseList = res.data.list as Problem[];
      if (!responseList || responseList.length <= 0) {
        pagination.value = { ...pagination.value, total: 0 };
        problemAttemptStatus = {};
        ShowTextTipsInfo(globalProperties, "未找到记录");
        return;
      }
      responseList.forEach((item) => {
        const result = ParseProblem(item, tagsMap);
        problemViews.value?.push(result);
      });
      pagination.value = { ...pagination.value, total: res.data.total_count };
      problemAttemptStatus = res.data.problem_attempt_status;
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
  }
};

const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  // 更新 URL 查询参数
  await router.push({
    query: { ...route.query, page: pageInfo.current, page_size: pageInfo.pageSize },
  });
};

// 初始化分页信息
onMounted(async () => {
  viewActive = true;

  dataLoading.value = true;

  problemTags.value = [];
  GetProblemTagList(-1)
    .then((res) => {
      if (res.code === 0) {
        problemTags.value = res.data.list;
        for (let i = 0; i < res.data.list.length; i++) {
          const tag = res.data.list[i] as ProblemTag;
          tagsMap[tag.id] = tag;
          // 题目挂的是**具体叫法**（problem_tag.tag_id 指向叫法行），所以每个叫法的 id
          // 都要能查到名字。只登记概念 id 的话，挂在别名上的标签在题目列表里显示为空。
          for (const member of tag.members ?? []) {
            tagsMap[member.id] = member;
          }
        }

        watchHandle = watch(
          () => route.query,
          (newQuery) => {
            if (!viewActive) {
              return;
            }
            searchProblemForm.value.oj = (newQuery.oj as string) || "";
            searchProblemForm.value.title = (newQuery.title as string) || "";
            searchProblemForm.value.tag = (newQuery.tag as string) || "";
            // URL 是多选状态的唯一来源：浏览器前进/后退、分享链接都要能把多选框还原
            selectedTags.value = parseTagString(searchProblemForm.value.tag);
            searchProblemForm.value.tagMode = newQuery.tag_mode === "all" ? "all" : "any";
            searchProblemForm.value.difficulty = parseInt(newQuery.difficulty as string) || 0;
            searchProblemForm.value.private = (newQuery.private as string) === "1";
            const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
            const queryPageSize = parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;
            currentPage = queryPage;
            currentPageSize = queryPageSize;
            pagination.value = { ...pagination.value, current: currentPage, pageSize: currentPageSize };
            fetchData({ current: currentPage, pageSize: currentPageSize }, true);
          },
          { immediate: true }
        );
      } else {
        // 标签云加载失败：侧栏不展示标签，用户仍可用表单按标签名搜索
      }
    })
    .catch((err) => {
      console.error(err);
    });
});

onBeforeUnmount(() => {
  viewActive = false;

  if (watchHandle) {
    watchHandle();
  }
});
</script>

<template>
  <!-- 移动端布局：顶部操作栏 + 列表 + 右侧筛选 Drawer -->
  <div v-if="isMobile" class="problem-list-mobile">
    <div class="mobile-toolbar">
      <t-button
        theme="default"
        variant="outline"
        class="mobile-toolbar-btn"
        @click="showFilterDrawer = true"
      >
        <template #icon>
          <t-icon name="filter" />
        </template>
        筛选
        <t-badge
          v-if="activeFilterCount > 0"
          :count="activeFilterCount"
          shape="round"
          color="var(--td-brand-color)"
          :offset="[6, -6]"
        />
      </t-button>
      <t-button
        v-if="hasEditAuth"
        theme="primary"
        class="mobile-toolbar-btn"
        @click="handleClickCreate"
      >
        <template #icon>
          <t-icon name="add" />
        </template>
        新建
      </t-button>
    </div>

    <t-card class="mobile-list-card">
      <div style="overflow-x: auto; width: 100%">
        <t-table
          :data="problemViews"
          :columns="listColumns"
          row-key="id"
          vertical-align="top"
          :hover="true"
          :pagination="pagination"
          table-layout="auto"
          :loading="dataLoading"
          @page-change="onPageChange"
        />
      </div>
    </t-card>

    <!-- 移动端筛选抽屉：复用桌面端筛选表单和爬虫表单 -->
    <t-drawer
      v-model:visible="showFilterDrawer"
      header="筛选"
      placement="right"
      size="80%"
      :close-on-esc-keydown="true"
      :show-overlay="true"
    >
      <t-form :data="searchProblemForm" @submit="handleDrawerSearch" @reset="handleDrawerReset">
        <t-form-item label="OJ">
          <t-select v-model="searchProblemForm.oj" :options="ojOptions" placeholder="请选择OJ" clearable></t-select>
        </t-form-item>
        <t-form-item label="标题">
          <t-input v-model="searchProblemForm.title" placeholder="请输入关键词"></t-input>
        </t-form-item>
        <t-form-item label="标签">
          <t-space direction="vertical" style="width: 100%">
            <t-select
              v-model="selectedTags"
              :options="tagOptions"
              :filter="filterTagOption"
              multiple
              filterable
              clearable
              creatable
              :min-collapsed-num="2"
              placeholder="选择标签（可多选，支持输入任一叫法）"
            ></t-select>
            <t-radio-group v-model="searchProblemForm.tagMode" variant="default-filled" size="small">
              <t-radio-button value="any">含任一</t-radio-button>
              <t-radio-button value="all">含全部</t-radio-button>
            </t-radio-group>
          </t-space>
        </t-form-item>
        <t-form-item label="难度">
          <t-select v-model="searchProblemForm.difficulty" :options="difficultyOptions"></t-select>
        </t-form-item>
        <t-form-item v-if="hasEditAuth" label="私有">
          <t-switch v-model="searchProblemForm.private"></t-switch>
        </t-form-item>
      </t-form>

      <!-- 抓取题目：移动端放在筛选 Drawer 内，仅管理员可见 -->
      <template v-if="hasEditAuth">
        <t-divider align="left">抓取题目</t-divider>
        <t-form :data="crawlProblemForm" @submit="handleClickCrawl">
          <t-form-item label="OJ">
            <t-select v-model="crawlProblemForm.oj" :options="ojOptions" placeholder="请选择OJ" clearable></t-select>
          </t-form-item>
          <t-form-item label="题目">
            <t-input v-model="crawlProblemForm.problem" placeholder="请输入原始题号"></t-input>
          </t-form-item>
          <t-form-item>
            <t-button theme="primary" type="submit" :loading="isCrawling">前往</t-button>
          </t-form-item>
        </t-form>
      </template>

      <template #footer>
        <t-space>
          <t-button theme="primary" @click="handleDrawerSearch">确定</t-button>
          <t-button theme="danger" variant="outline" @click="handleDrawerReset">重置</t-button>
        </t-space>
      </template>
    </t-drawer>
  </div>

  <!-- 桌面端布局：左右双栏，筛选在右侧 -->
  <t-row v-else>
    <t-col :span="9">
      <t-card style="margin: 10px">
        <div style="overflow-x: auto; width: 100%">
          <t-table
            :data="problemViews"
            :columns="listColumns"
            row-key="id"
            vertical-align="top"
            :hover="true"
            :pagination="pagination"
            table-layout="auto"
            :loading="dataLoading"
            @page-change="onPageChange"
          />
        </div>
      </t-card>
    </t-col>
    <t-col :span="3">
      <div style="margin: 10px">
        <div v-if="hasEditAuth" class="dida-operation-container">
          <t-space>
            <t-button @click="handleClickCreate">新建</t-button>
          </t-space>
        </div>
        <t-card class="sh-card">
          <t-form :model="searchProblemForm" @submit="handleClickSearch" @reset="handleClickReset">
            <t-form-item label="OJ">
              <t-select v-model="searchProblemForm.oj" :options="ojOptions" placeholder="请选择OJ" clearable></t-select>
            </t-form-item>
            <t-form-item label="标题">
              <t-input v-model="searchProblemForm.title" placeholder="请输入关键词"></t-input>
            </t-form-item>
            <t-form-item label="标签">
              <t-space direction="vertical" style="width: 100%">
                <t-select
                  v-model="selectedTags"
                  :options="tagOptions"
                  :filter="filterTagOption"
                  multiple
                  filterable
                  clearable
                  creatable
                  :min-collapsed-num="2"
                  placeholder="选择标签（可多选，支持输入任一叫法）"
                ></t-select>
                <t-radio-group v-model="searchProblemForm.tagMode" variant="default-filled" size="small">
                  <t-radio-button value="any">含任一</t-radio-button>
                  <t-radio-button value="all">含全部</t-radio-button>
                </t-radio-group>
              </t-space>
            </t-form-item>
            <t-form-item label="难度">
              <t-select v-model="searchProblemForm.difficulty" :options="difficultyOptions"></t-select>
            </t-form-item>
            <t-form-item v-if="hasEditAuth" label="私有">
              <t-switch v-model="searchProblemForm.private"></t-switch>
            </t-form-item>
            <t-form-item>
              <t-space>
                <t-button theme="primary" type="submit">搜索</t-button>
                <t-button theme="danger" type="reset">重置</t-button>
              </t-space>
            </t-form-item>
          </t-form>
        </t-card>
        <t-card class="sh-card">
          <t-form :model="crawlProblemForm" @submit="handleClickCrawl">
            <t-form-item label="OJ">
              <t-select v-model="crawlProblemForm.oj" :options="ojOptions" placeholder="请选择OJ" clearable></t-select>
            </t-form-item>
            <t-form-item label="题目">
              <t-input v-model="crawlProblemForm.problem" placeholder="请输入原始题号"></t-input>
            </t-form-item>
            <t-form-item>
              <t-button theme="primary" type="submit" :loading="isCrawling">前往</t-button>
            </t-form-item>
          </t-form>
        </t-card>
        <t-card v-if="problemTags && problemTags.length > 0" class="sh-card sh-background-black">
          <t-button
            v-for="tag in visibleTags"
            :key="tag.id"
            class="sh-tag-button"
            theme="default"
            variant="outline"
            :ghost="true"
            @click="() => handleClickTag(tag)"
          >
            {{ tag.name }}
          </t-button>
          <!-- 全量标签有 360+ 个，全渲染会把侧栏撑成一条长墙；这里只展示置顶与最近
               改动过的前 100 个，其余走标签单页（下一批接上） -->
          <!-- 与其他标签按钮同一套 theme：列表页标签有特殊背景色，
               用 primary 会跟它打架。文案 ...(+N) 里的 N 是没显示出来的个数，
               没有剩余时只显示 ...。点进标签单页看全部 -->
          <t-button
            class="sh-tag-button"
            theme="default"
            variant="outline"
            :ghost="true"
            @click="goTagPage"
          >
            {{ hiddenTagCount > 0 ? `...(+${hiddenTagCount})` : "..." }}
          </t-button>
        </t-card>
      </div>
    </t-col>
